:root {
  --navy: #17394a;
  --ocean: #167b91;
  --aqua: #dff4f1;
  --foam: #f8fcfb;
  --coral: #ed765c;
  --gold: #f5c75d;
  --line: #b9deda;
  --muted: #5b7b83;
  --white: #ffffff;
}

.feeding-card {
  width: 460px;
  box-sizing: border-box;
  padding: 18px;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: var(--foam);
  color: var(--navy);
}

.card-header,
.tank-row,
.card-footer,
.feed-item {
  display: flex;
  align-items: center;
}

.card-header,
.card-footer {
  justify-content: space-between;
}

.title-block {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.eyebrow {
  margin: 0;
  color: var(--ocean);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
}

.title-block h2 {
  margin: 0;
  font-size: 22px;
  line-height: 1.1;
}

.ready-badge {
  padding: 5px 10px;
  border-radius: 999px;
  background: var(--gold);
  color: var(--navy);
  font-size: 12px;
  font-weight: 700;
}

.tank-row {
  gap: 11px;
  margin: 16px 0 12px;
  padding: 11px 12px;
  border-radius: 12px;
  background: var(--aqua);
}

.tank-icon {
  display: grid;
  width: 34px;
  height: 34px;
  place-items: center;
  border-radius: 10px;
  background: var(--white);
  font-size: 19px;
}

.tank-copy {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.tank-copy strong {
  font-size: 14px;
}

.tank-copy p {
  margin: 0;
  color: var(--muted);
  font-size: 12px;
}

.feed-list {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.feed-item {
  flex-direction: column;
  align-items: flex-start;
  gap: 4px;
  padding: 10px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: var(--white);
  color: var(--muted);
  font-size: 11px;
}

.feed-item strong {
  color: var(--navy);
  font-size: 14px;
}

.card-footer {
  margin-top: 15px;
  padding-top: 14px;
  border-top: 1px solid var(--line);
}

.keeper {
  color: var(--muted);
  font-size: 12px;
}

.complete-button {
  border: 0;
  border-radius: 9px;
  padding: 9px 14px;
  background: var(--coral);
  color: var(--white);
  font-size: 13px;
  font-weight: 700;
}
